// Opt-in live compatibility check. The application remains on Browserbase until
// the installed Stagehand runtime can initialize against Notte Cloud.
import { localBrowser, Stagehand } from '@browserbasehq/stagehand';
import { NotteClient } from 'notte-sdk';
import assert from 'node:assert/strict';

// SDK/transport logging can contain credentials. Emit only our allowlisted report.
const emit = (value) => process.stdout.write(`${JSON.stringify(value)}\n`);
console.log = console.warn = console.error = console.info = console.debug = () => {};
const session = new NotteClient({ timeoutMs: 30_000 }).Session({
  max_duration_minutes: 2, idle_timeout_minutes: 1,
});
let browser, stagehand;
let started = false;
let phase = 'launch';
try {
  await session.start({ signal: AbortSignal.timeout(30_000) });
  started = true;
  phase = 'connect';
  browser = await localBrowser.connect({ cdpUrl: await session.cdpUrl() });
  phase = 'create';
  stagehand = await Stagehand.create({ browser, logging: { level: 'off' } });
  phase = 'navigate';
  const page = (await browser.context.pages())[0];
  await page.goto('https://example.com');
  phase = 'assert';
  const title = await page.title();
  assert.equal(title, 'Example Domain');
  const snapshot = await page.snapshot();
  emit({ passed: true, title, snapshotNonempty: JSON.stringify(snapshot).length > 20 });
} catch (error) {
  // Inspect locally, never emit raw messages, error names, stack traces or URLs.
  const message = String(error?.message ?? '');
  emit({ passed: false, phase,
    httpStatus: Number.isInteger(error?.statusCode) ? error.statusCode : null,
    networkFailure: error instanceof TypeError,
    extensionManagementDenied:
    message.includes('Extensions.loadUnpacked') && message.includes('not permitted') });
  process.exitCode = 1;
} finally {
  for (const [resource, close] of [
    ['stagehand', () => stagehand?.close()],
    ['browser', () => browser?.close()],
    ['session', () => started ? session.stop() : undefined],
  ]) {
    if ((resource === 'stagehand' && !stagehand) ||
        (resource === 'browser' && !browser) ||
        (resource === 'session' && !started)) {
      emit({ cleanup: resource, skipped: true });
      continue;
    }
    try { await close(); emit({ cleanup: resource, passed: true }); }
    catch { emit({ cleanup: resource, passed: false }); process.exitCode = 1; }
  }
  if (started) {
    try {
      const status = await session.status();
      emit({ stopped: status.status === 'closed' });
      if (status.status !== 'closed') process.exitCode = 1;
    } catch { emit({ statusCheck: false }); process.exitCode = 1; }
  }
}

