import {Stagehand} from '@browserbasehq/stagehand';
import {NotteClient} from 'notte-sdk';

export async function withNotteStagehand(workflow, {
  createSession = () => new NotteClient().Session({max_duration_minutes: 2, idle_timeout_minutes: 2}),
  createStagehand = options => new Stagehand(options),
} = {}) {
  const session = createSession();
  await session.start();
  let stagehand;
  let failed = false;
  try {
    stagehand = createStagehand({
      env: 'LOCAL',
      disableAPI: true,
      localBrowserLaunchOptions: {cdpUrl: await session.cdpUrl()},
      verbose: 0,
      disablePino: true,
      logger: () => {},
    });
    await stagehand.init();
    return await workflow(stagehand);
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    let cleanupError;
    let cleanupFailed = false;
    for (const cleanup of [() => stagehand?.close(), () => session.stop()]) {
      try { await cleanup(); } catch (error) {
        if (!cleanupFailed) { cleanupError = error; cleanupFailed = true; }
      }
    }
    if (!failed && cleanupFailed) throw cleanupError;
  }
}
